Here's a modern MSTest test class for `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private MockHttpMessageHandler _handler = null!;
    private DataFetcher _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _handler = new MockHttpMessageHandler();
        _sut = new DataFetcher(new HttpClient(_handler));
    }

    // Modern MSTest uses Task return + async/await natively — no need for .Result or .GetAwaiter()
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_WhenSuccessful()
    {
        _handler.ResponseContent = "hello";
        _handler.StatusCode = HttpStatusCode.OK;

        var result = await _sut.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    // Use [Timeout] in ms to guard against hangs — applies to async tests too
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_ThrowsOnNonSuccess()
    {
        _handler.StatusCode = HttpStatusCode.InternalServerError;

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => _sut.FetchAsync("https://example.com"));
    }

    // Test that your code actually forwards the CancellationToken
    [TestMethod]
    public async Task FetchAsync_HonoursCancellationToken()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel(); // pre-cancel

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => _sut.FetchAsync("https://example.com", cts.Token));
    }

    // Verify cancellation mid-flight via a delayed handler
    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_CancelsDuringRequest()
    {
        using var cts = new CancellationTokenSource();
        _handler.SimulateDelay = TimeSpan.FromSeconds(10);

        var task = _sut.FetchAsync("https://example.com", cts.Token);
        cts.CancelAfter(TimeSpan.FromMilliseconds(50));

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(() => task);
    }

    // Minimal mock handler — avoids heavy mocking libraries
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;
        public string ResponseContent { get; set; } = string.Empty;
        public TimeSpan SimulateDelay { get; set; } = TimeSpan.Zero;

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (SimulateDelay > TimeSpan.Zero)
                await Task.Delay(SimulateDelay, cancellationToken);

            cancellationToken.ThrowIfCancellationRequested();

            return new HttpResponseMessage(StatusCode)
            {
                Content = new StringContent(ResponseContent)
            };
        }
    }
}
```

**Key patterns demonstrated:**

- **`async Task` test methods** — MSTest natively awaits them; never use `async void`
- **`[Timeout(ms)]`** — prevents hung tests; works with async methods
- **`Assert.ThrowsExceptionAsync<T>`** — the async counterpart for exception assertions
- **Custom `HttpMessageHandler`** — avoids mocking frameworks; gives full control over responses, delays, and cancellation propagation
- **Pre-cancelled and mid-flight cancellation** — two complementary tests that verify the token is actually forwarded through the call chain
